const input = $input.first().json;

return [
  {
    json: {
      ok: false,
      status: 'missing_file',
      request: input.request,
      user: input.user,
      active_session: input.active_session,
      response: {
        ok: false,
        status: 'missing_file',
        reply: {
          type: 'text',
          text: 'لم أستقبل أي ملف. أرسل ملف PDF أو Word أو صورة حتى أستخرج النص.',
          buttons: [
            { label: '🏠 القائمة الرئيسية', action: 'MAIN_MENU' },
            { label: '❌ إلغاء', action: 'CANCEL' }
          ],
          file: null
        },
        data: {},
        error: 'missing_file'
      }
    }
  }
];

const previous = $('Normalize File Input').first().json;
const telegramResponse = $input.first().json || {};

const filePath = telegramResponse?.result?.file_path;

if (!filePath) {
  throw new Error('Telegram getFile did not return file_path');
}

return [
  {
    json: {
      ...previous,
      telegram_file_path: filePath
    }
  }
];

const item = $input.first();

const json = item.json || {};
const binary = item.binary || {};

const file = json.file || {};
const mime = String(file.mime_type || '').toLowerCase();
const name = String(file.file_name || '').toLowerCase();

let fileType = 'unknown';

if (mime.includes('pdf') || name.endsWith('.pdf')) {
  fileType = 'pdf';
} else if (
  mime.includes('word') ||
  mime.includes('officedocument') ||
  name.endsWith('.docx') ||
  name.endsWith('.doc')
) {
  fileType = 'docx';
} else if (
  mime.includes('image') ||
  name.endsWith('.jpg') ||
  name.endsWith('.jpeg') ||
  name.endsWith('.png') ||
  name.endsWith('.webp')
) {
  fileType = 'image';
} else if (
  mime.includes('text') ||
  name.endsWith('.txt')
) {
  fileType = 'txt';
}

if (!binary.data) {
  throw new Error(
    'Missing binary.data in Detect File Type. Check Download Telegram File output field name.'
  );
}

return [
  {
    json: {
      ...json,
      file_type: fileType
    },
    binary
  }
];

const base = $('Detect File Type').first().json;
const extracted = $input.first().json || {};

const rawText =
  extracted.text ||
  extracted.data ||
  extracted.content ||
  extracted.extractedText ||
  extracted.output ||
  '';

return [
  {
    json: {
      ...base,
      raw_text: String(rawText || ''),
      extraction_method: 'pdf_extract'
    }
  }
];

